"""Pydantic shape of an auto-generated HuggingFace dataset card.

The card is generated from ``_meta`` (entry counts, source mix, date
range) plus per-source default-license blurbs. The pydantic layer keeps
the YAML front-matter and the Markdown body in lockstep — generators
can construct it programmatically and we serialize once.
"""
from __future__ import annotations

from typing import Dict, List, Optional

from pydantic import BaseModel, ConfigDict, Field


class LicenseInfo(BaseModel):
    model_config = ConfigDict(extra="forbid")

    source: str
    short: str          # e.g. "per-track-page", "per-item"
    notes: str = ""


# Default per-source license blurb. Always per-row in practice; users
# should review before publishing.
DEFAULT_LICENSES: Dict[str, LicenseInfo] = {
    "youtube": LicenseInfo(
        source="youtube",
        short="per-channel",
        notes="YouTube content licensing varies per channel; the Standard "
              "YouTube License applies unless creators specify otherwise.",
    ),
    "youtube_music": LicenseInfo(
        source="youtube_music",
        short="per-rightsholder",
        notes="YT Music tracks are owned by the rightsholders listed on "
              "the source page.",
    ),
    "bandcamp": LicenseInfo(
        source="bandcamp",
        short="per-track-page",
        notes="Bandcamp pages indicate the license; many tracks are "
              "Creative Commons.",
    ),
    "soundcloud": LicenseInfo(
        source="soundcloud",
        short="per-track-page",
        notes="SoundCloud uploaders set the license per track.",
    ),
    "internet_archive": LicenseInfo(
        source="internet_archive",
        short="per-item",
        notes="Internet Archive items are typically public-domain or "
              "Creative-Commons; check each item page.",
    ),
}


class DatasetCard(BaseModel):
    """Both the YAML front-matter and the Markdown body of the README."""

    model_config = ConfigDict(extra="forbid")

    name: str
    description: str
    license: str = "other"            # SPDX or "other"
    languages: List[str] = Field(default_factory=lambda: ["en"])
    tags: List[str] = Field(default_factory=lambda: ["media-archivist"])

    total_entries: int = 0
    source_mix: Dict[str, int] = Field(default_factory=dict)
    date_range: Optional[str] = None  # e.g. "2018–2026" if derivable
    canonical_records: Optional[int] = None
    quarantined: Optional[int] = None
    licenses_by_source: Dict[str, LicenseInfo] = Field(default_factory=dict)

    def to_markdown(self) -> str:
        front = [
            "---",
            f"name: {self.name}",
            f"license: {self.license}",
            f"language:",
        ]
        for lang in self.languages:
            front.append(f"  - {lang}")
        front.append("tags:")
        for tag in self.tags:
            front.append(f"  - {tag}")
        front.append("---")

        body = [
            f"# {self.name}",
            "",
            self.description,
            "",
            "## Stats",
            "",
            f"- Total entries: {self.total_entries}",
        ]
        if self.canonical_records is not None:
            body.append(f"- Canonical records: {self.canonical_records}")
        if self.quarantined is not None:
            body.append(f"- Quarantined rows: {self.quarantined}")
        if self.date_range:
            body.append(f"- Date range: {self.date_range}")
        if self.source_mix:
            body.append("")
            body.append("### Source mix")
            body.append("")
            body.append("| Source | Entries |")
            body.append("| --- | --- |")
            for src, n in sorted(self.source_mix.items()):
                body.append(f"| `{src}` | {n} |")

        if self.licenses_by_source:
            body.append("")
            body.append("## Licensing")
            body.append("")
            body.append("Licensing is **per-row** in practice; the rows in "
                        "this dataset originated from the following sources:")
            body.append("")
            for src, info in sorted(self.licenses_by_source.items()):
                body.append(f"- `{src}` — {info.short}. {info.notes}")

        body.append("")
        body.append("## Provenance")
        body.append("")
        body.append("Generated by [`media_archivist`]"
                    "(https://github.com/TigreGotico/media-archivist).")
        return "\n".join(front + [""] + body) + "\n"
